import{_ as n,f as a,o as e,aq as l}from"./chunks/framework.BvNt3gUw.js";const d=JSON.parse('{"title":"Telemetry","description":"","frontmatter":{},"headers":[],"relativePath":"digging-deeper/telemetry.md","filePath":"en/digging-deeper/telemetry.md","lastUpdated":1789895472000}'),o={name:"digging-deeper/telemetry.md"};function p(r,s,t,c,i,y){return e(),a("div",null,s[0]||(s[0]=[l(`<h1 id="telemetry" tabindex="-1">Telemetry <a class="header-anchor" href="#telemetry" aria-label="Permalink to “Telemetry”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Goravel provides an observability module built on top of <a href="https://opentelemetry.io" target="_blank" rel="noreferrer">OpenTelemetry</a> that can be operated using <code>facades.Telemetry()</code>. It allows you to collect traces, metrics, and logs from your application and export them to any OTLP-compatible backend, such as Jaeger, Prometheus, Grafana, or Datadog.</p><p>The module is integrated with the application lifecycle: providers are configured in a single configuration file, buffered data is flushed automatically when the application shuts down, and built-in instrumentation is available for the HTTP server, the HTTP client, gRPC, and the logger.</p><p>If you are new to OpenTelemetry, the module revolves around three signals:</p><ul><li><strong>Traces</strong> record the full path of a request as it travels through your services. Each trace is a tree of spans, where a span represents a single timed operation, such as an HTTP request, a database query, or a function call.</li><li><strong>Metrics</strong> are numerical measurements aggregated over time, such as request counts, durations, or memory usage.</li><li><strong>Logs</strong> are timestamped records of events, which can be linked to the trace that produced them.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h2><p>The telemetry module is optional, you can install it using the <code>package:install</code> command:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> package:install</span><span style="color:#101820;"> Telemetry</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This command performs the following actions:</p><ul><li>Creates the <code>config/telemetry.go</code> configuration file;</li><li>Creates the <code>facades/telemetry.go</code> facade file;</li><li>Registers <code>&amp;telemetry.ServiceProvider{}</code> in <code>bootstrap/providers.go</code>;</li><li>Adds an <code>otel</code> channel to <code>config/logging.go</code> for log export.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>All of the configuration options live in the <code>config/telemetry.go</code> file. The <code>service</code> section defines the identity attached to every trace, metric, and log record, this is what observability platforms use to group your data:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;service&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;name&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">        config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;APP_NAME&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;goravel&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    &quot;version&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">     config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;APP_VERSION&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    &quot;environment&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;APP_ENV&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>You can attach additional static metadata (e.g., <code>k8s.pod.name</code>, <code>region</code>, <code>team</code>) to all telemetry data using the <code>resource</code> section.</p><h3 id="enabling-signals" tabindex="-1">Enabling Signals <a class="header-anchor" href="#enabling-signals" aria-label="Permalink to “Enabling Signals”">​</a></h3><p>Each signal (traces, metrics, and logs) is disabled by default. To enable a signal, point its <code>exporter</code> option to one of the exporter definitions in the <code>exporters</code> section. The easiest way is through your <code>.env</code> file:</p><div class="language-ini line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">OTEL_TRACES_EXPORTER</span><span style="color:#68747D;">=</span><span style="color:#101820;">otlptrace</span></span>
<span class="line"><span style="color:#101820;">OTEL_METRICS_EXPORTER</span><span style="color:#68747D;">=</span><span style="color:#101820;">otlpmetric</span></span>
<span class="line"><span style="color:#101820;">OTEL_LOGS_EXPORTER</span><span style="color:#68747D;">=</span><span style="color:#101820;">otlplog</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Setting an exporter to an empty string disables the corresponding signal entirely.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>During local development, you can set any of these to <code>console</code> to print telemetry data directly to stdout instead of sending it to a backend.</p></div><h3 id="exporters" tabindex="-1">Exporters <a class="header-anchor" href="#exporters" aria-label="Permalink to “Exporters”">​</a></h3><p>The <code>exporters</code> section defines how the data leaves your application. Each entry is referenced by name from the signal sections, three drivers are supported: <code>otlp</code>, <code>console</code>, and <code>custom</code>.</p><h4 id="otlp" tabindex="-1">OTLP <a class="header-anchor" href="#otlp" aria-label="Permalink to “OTLP”">​</a></h4><p>The <code>otlp</code> driver sends data to any OpenTelemetry collector or vendor endpoint, using either <code>http/protobuf</code> (port 4318) or <code>grpc</code> (port 4317):</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;otlptrace&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;driver&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;">   &quot;otlp&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">    &quot;endpoint&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_EXPORTER_OTLP_TRACES_ENDPOINT&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;localhost:4318&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // Protocol: &quot;http/protobuf&quot; or &quot;grpc&quot;.</span></span>
<span class="line"><span style="color:#68747D;">    &quot;protocol&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_EXPORTER_OTLP_TRACES_PROTOCOL&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;http/protobuf&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // Set to false to require TLS/SSL.</span></span>
<span class="line"><span style="color:#68747D;">    &quot;insecure&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_EXPORTER_OTLP_TRACES_INSECURE&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> true</span><span style="color:#68747D;">),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // Compression: &quot;gzip&quot; or &quot;&quot; (none).</span></span>
<span class="line"><span style="color:#68747D;">    &quot;compression&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_EXPORTER_OTLP_TRACES_COMPRESSION&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // TLS certificate file paths. Leave empty to use system roots.</span></span>
<span class="line"><span style="color:#68747D;">    &quot;tls&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">        &quot;ca&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">   config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_EXPORTER_OTLP_TRACES_CERTIFICATE&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">        &quot;cert&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_EXPORTER_OTLP_TRACES_CLIENT_CERTIFICATE&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">        &quot;key&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">  config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_EXPORTER_OTLP_TRACES_CLIENT_KEY&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    },</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // Retry with exponential backoff on export failure.</span></span>
<span class="line"><span style="color:#68747D;">    &quot;retry&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">        &quot;enabled&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">          true</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">        &quot;initial_interval&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;5s&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">        &quot;max_interval&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;">     &quot;30s&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">        &quot;max_elapsed_time&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;1m&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">    },</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><p>The <code>endpoint</code> option accepts either a bare <code>host:port</code> pair or a full URL. When a URL with a scheme is provided (e.g., <code>https://otlp.example.com/v1/traces</code>), the scheme and path determine the TLS setting and export path, and the <code>insecure</code> option is ignored.</p><p>If your backend requires authentication, such as a vendor API key, you may attach headers to every export request using the <code>headers</code> option:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;otlptrace&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;driver&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;">   &quot;otlp&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">    &quot;endpoint&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_EXPORTER_OTLP_TRACES_ENDPOINT&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;localhost:4318&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    &quot;headers&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">        &quot;x-api-key&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_EXPORTER_API_KEY&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    },</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>The metric exporter additionally supports the <code>metric_temporality</code> option: <code>cumulative</code> (Prometheus), <code>delta</code> (Datadog/StatsD), or <code>lowmemory</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To see your traces locally, you can run Jaeger with a single command, it accepts OTLP on the default ports and requires no extra configuration:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">docker</span><span style="color:#101820;"> run</span><span style="color:#101820;"> --rm</span><span style="color:#101820;"> -p</span><span style="color:#101820;"> 16686:16686</span><span style="color:#101820;"> -p</span><span style="color:#101820;"> 4317:4317</span><span style="color:#101820;"> -p</span><span style="color:#101820;"> 4318:4318</span><span style="color:#101820;"> jaegertracing/jaeger:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then set <code>OTEL_TRACES_EXPORTER=otlptrace</code> and open <code>http://localhost:16686</code>.</p></div><h4 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to “Console”">​</a></h4><p>The <code>console</code> driver prints telemetry data to stdout, which is useful for debugging your instrumentation locally:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;console&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;driver&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;">       &quot;console&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">    &quot;pretty_print&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> true</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h4 id="custom" tabindex="-1">Custom <a class="header-anchor" href="#custom" aria-label="Permalink to “Custom”">​</a></h4><p>If you need to export data to a destination that is not supported out of the box, you may provide your own exporter using the <code>custom</code> driver. The <code>via</code> key accepts either a ready-made instance or a factory function, depending on the signal the exporter is used for:</p><table tabindex="0"><thead><tr><th>Signal</th><th>Instance</th><th>Factory</th></tr></thead><tbody><tr><td>Traces</td><td><code>sdktrace.SpanExporter</code></td><td><code>func(context.Context) (sdktrace.SpanExporter, error)</code></td></tr><tr><td>Metrics</td><td><code>sdkmetric.Reader</code></td><td><code>func(context.Context) (sdkmetric.Reader, error)</code></td></tr><tr><td>Logs</td><td><code>sdklog.Exporter</code></td><td><code>func(context.Context) (sdklog.Exporter, error)</code></td></tr></tbody></table><p>For example, to write spans to a file instead of stdout:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">context</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">os</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">go.opentelemetry.io/otel/exporters/stdout/stdouttrace</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#101820;">    sdktrace </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">go.opentelemetry.io/otel/sdk/trace</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">&quot;custom&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;driver&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;custom&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">    &quot;via&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> func</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx context</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> (</span><span style="color:#101820;">sdktrace</span><span style="color:#68747D;">.</span><span style="color:#101820;">SpanExporter</span><span style="color:#68747D;">,</span><span style="color:#101820;"> error</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">        file</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> os</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Create</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;storage/logs/traces.json&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">        if err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">            return nil</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err</span></span>
<span class="line"><span style="color:#68747D;">        }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">        return stdouttrace</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">New</span><span style="color:#68747D;">(</span><span style="color:#101820;">stdouttrace</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithWriter</span><span style="color:#68747D;">(</span><span style="color:#101820;">file</span><span style="color:#68747D;">))</span></span>
<span class="line"><span style="color:#68747D;">    },</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h3 id="sampling" tabindex="-1">Sampling <a class="header-anchor" href="#sampling" aria-label="Permalink to “Sampling”">​</a></h3><p>Recording every trace can be expensive in high-traffic applications. The <code>traces.sampler</code> section controls which traces are recorded:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;sampler&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    // If true, respects the sampling decision of the upstream service.</span></span>
<span class="line"><span style="color:#68747D;">    &quot;parent&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_TRACES_SAMPLER_PARENT&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> true</span><span style="color:#68747D;">),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // &quot;always_on&quot;, &quot;always_off&quot; or &quot;traceidratio&quot;</span></span>
<span class="line"><span style="color:#68747D;">    &quot;type&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_TRACES_SAMPLER_TYPE&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;always_on&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // The ratio for &quot;traceidratio&quot; sampling, e.g., 0.1 records ~10% of traces.</span></span>
<span class="line"><span style="color:#68747D;">    &quot;ratio&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_TRACES_SAMPLER_RATIO&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> 0.05),</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>When <code>parent</code> is enabled, your service follows the sampling decision already made by the calling service, ensuring distributed traces are never broken in the middle.</p><h3 id="processors" tabindex="-1">Processors <a class="header-anchor" href="#processors" aria-label="Permalink to “Processors”">​</a></h3><p>Traces and logs are handed to their exporters through a processor. The default <code>batch</code> processor buffers data and pushes it on an interval, which is the recommended setting for production. The <code>simple</code> processor exports each record synchronously and should only be used for debugging:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;processor&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;type&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">     config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_TRACE_PROCESSOR_TYPE&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;batch&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    &quot;interval&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_TRACE_EXPORT_INTERVAL&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;5s&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    &quot;timeout&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">  config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_TRACE_EXPORT_TIMEOUT&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;30s&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Metrics use a periodic reader instead, configured by <code>metrics.reader.interval</code> (default <code>60s</code>).</p><h2 id="tracing" tabindex="-1">Tracing <a class="header-anchor" href="#tracing" aria-label="Permalink to “Tracing”">​</a></h2><h3 id="creating-spans" tabindex="-1">Creating Spans <a class="header-anchor" href="#creating-spans" aria-label="Permalink to “Creating Spans”">​</a></h3><p>To create a span, request a tracer from the <code>Telemetry</code> facade using the <code>Tracer</code> method, then call <code>Start</code>. The first argument is a <code>context.Context</code>, if the context already contains a span (for example, one started by the HTTP middleware), the new span is automatically attached as its child.</p><p>The <code>Tracer</code> argument (<code>&quot;app&quot;</code> above) is the <strong>instrumentation scope name</strong>: it identifies the code that produced the span. Use a stable name that points back to the instrumenting code, by convention the package import path (for example <code>github.com/you/app/services</code>) or, for application code, the application or module name. It is recorded on every span as <code>otel.scope.name</code>, so your backend can group and filter spans by the component that emitted them. The framework&#39;s built-in instrumentation uses its own scope (for example <code>github.com/goravel/framework/telemetry/instrumentation/http</code>), which keeps your spans distinct from the framework&#39;s.</p><p>The following service traces an order through its processing steps: the <code>Process</code> method opens a span, records what happened on it, and passes the returned context down so that <code>chargePayment</code> becomes a child span within the same trace:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">app/services/order_service.go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">package services</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">context</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">github.com/goravel/framework/telemetry</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">goravel/app/facades</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">type OrderService struct </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">r </span><span style="color:#68747D;">*</span><span style="color:#101820;">OrderService</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Process</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx context</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">,</span><span style="color:#101820;"> orderID </span><span style="color:#101820;">string</span><span style="color:#68747D;">)</span><span style="color:#101820;"> error </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> span </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Telemetry</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Tracer</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;app&quot;</span><span style="color:#68747D;">).</span><span style="color:#0077B3;">Start</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;order.process&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">    defer span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">End</span><span style="color:#68747D;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">SetAttributes</span><span style="color:#68747D;">(</span><span style="color:#101820;">telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;order.id&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> orderID</span><span style="color:#68747D;">))</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    if err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> r</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">chargePayment</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> orderID</span><span style="color:#68747D;">);</span><span style="color:#101820;"> err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">        span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RecordError</span><span style="color:#68747D;">(</span><span style="color:#101820;">err</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">        span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">SetStatus</span><span style="color:#68747D;">(</span><span style="color:#101820;">telemetry</span><span style="color:#68747D;">.</span><span style="color:#101820;">CodeError</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;failed to charge payment&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">        return err</span></span>
<span class="line"><span style="color:#68747D;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">AddEvent</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;payment_charged&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    return nil</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">r </span><span style="color:#68747D;">*</span><span style="color:#101820;">OrderService</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> chargePayment</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx context</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">,</span><span style="color:#101820;"> orderID </span><span style="color:#101820;">string</span><span style="color:#68747D;">)</span><span style="color:#101820;"> error </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    // This span automatically becomes a child of &quot;order.process&quot;.</span></span>
<span class="line"><span style="color:#101820;">    _</span><span style="color:#68747D;">,</span><span style="color:#101820;"> span </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Telemetry</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Tracer</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;app&quot;</span><span style="color:#68747D;">).</span><span style="color:#0077B3;">Start</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;order.charge_payment&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">    defer span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">End</span><span style="color:#68747D;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // Charge the payment...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    return nil</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br></div></div><p>When the service is called from a controller, pass <code>ctx</code>. If the <a href="#http-server">HTTP server middleware</a> is registered, the spans are attached to the request&#39;s trace, so your backend shows the full picture: the HTTP request, the order processing, and the payment charge as one tree:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">app/http/controllers/order_controller.go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">r </span><span style="color:#68747D;">*</span><span style="color:#101820;">OrderController</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Store</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">)</span><span style="color:#101820;"> http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Response </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    if err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> r</span><span style="color:#68747D;">.</span><span style="color:#101820;">orders</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Process</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> ctx</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Request</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Input</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;order_id&quot;</span><span style="color:#68747D;">));</span><span style="color:#101820;"> err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">        return ctx</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Response</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Status</span><span style="color:#68747D;">(</span><span style="color:#101820;">http</span><span style="color:#68747D;">.</span><span style="color:#101820;">StatusInternalServerError</span><span style="color:#68747D;">).</span><span style="color:#0077B3;">Json</span><span style="color:#68747D;">(</span><span style="color:#101820;">http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Json</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">            &quot;error&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;failed to process order&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">        })</span></span>
<span class="line"><span style="color:#68747D;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    return ctx</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Response</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Success</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Json</span><span style="color:#68747D;">(</span><span style="color:#101820;">http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Json</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">        &quot;message&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;order processed&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">    })</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>The name passed to <code>Tracer</code> (and <code>Meter</code>) identifies the instrumentation scope, typically your application or package name, and is shown alongside each span in your backend.</p><h3 id="span-attributes" tabindex="-1">Span Attributes <a class="header-anchor" href="#span-attributes" aria-label="Permalink to “Span Attributes”">​</a></h3><p>You can attach key-value attributes to a span using the <code>SetAttributes</code> method. The <code>telemetry</code> package re-exports the OpenTelemetry attribute helpers so you don&#39;t need to import additional packages:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/telemetry</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">SetAttributes</span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">    telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;order.id&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;1234&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#101820;">    telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Int</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;order.items&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> 3),</span></span>
<span class="line"><span style="color:#101820;">    telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Bool</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;order.gift&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> false</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Attributes can also be set at creation time using the <code>WithAttributes</code> option:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> span </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> tracer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Start</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;process-order&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithAttributes</span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">    telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;order.id&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;1234&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="span-events" tabindex="-1">Span Events <a class="header-anchor" href="#span-events" aria-label="Permalink to “Span Events”">​</a></h3><p>Events mark a point in time within a span, such as a cache miss or a retry attempt. You can add them using the <code>AddEvent</code> method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">AddEvent</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;cache_miss&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithAttributes</span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">    telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;cache.key&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;user:42&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="recording-errors" tabindex="-1">Recording Errors <a class="header-anchor" href="#recording-errors" aria-label="Permalink to “Recording Errors”">​</a></h3><p>When an operation fails, two calls work together: <code>RecordError</code> attaches the error to the span as an event, and <code>SetStatus</code> marks the whole span as failed so it can be filtered in your backend. Calling <code>RecordError</code> alone does not change the span status:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">if err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RecordError</span><span style="color:#68747D;">(</span><span style="color:#101820;">err</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">    span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">SetStatus</span><span style="color:#68747D;">(</span><span style="color:#101820;">telemetry</span><span style="color:#68747D;">.</span><span style="color:#101820;">CodeError</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;failed to process order&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    return err</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="span-kinds" tabindex="-1">Span Kinds <a class="header-anchor" href="#span-kinds" aria-label="Permalink to “Span Kinds”">​</a></h3><p>By default, spans are created with the <code>internal</code> kind. When a span represents a boundary like publishing a message to a queue or consuming one, you can declare its role using the <code>WithSpanKind</code> option:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> span </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> tracer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Start</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;orders.publish&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithSpanKind</span><span style="color:#68747D;">(</span><span style="color:#101820;">telemetry</span><span style="color:#68747D;">.</span><span style="color:#101820;">SpanKindProducer</span><span style="color:#68747D;">))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Available kinds: <code>SpanKindInternal</code>, <code>SpanKindServer</code>, <code>SpanKindClient</code>, <code>SpanKindProducer</code>, <code>SpanKindConsumer</code>.</p><h3 id="the-current-span" tabindex="-1">The Current Span <a class="header-anchor" href="#the-current-span" aria-label="Permalink to “The Current Span”">​</a></h3><p>You don&#39;t always need to create a new span, often you just want to enrich the one that is already active, such as the span started by the <a href="#http-server">HTTP server middleware</a>. You can retrieve it from the context using the <code>SpanFromContext</code> function:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">go.opentelemetry.io/otel/trace</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">r </span><span style="color:#68747D;">*</span><span style="color:#101820;">OrderController</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Store</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">)</span><span style="color:#101820;"> http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Response </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    span </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> trace</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">SpanFromContext</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">    span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">SetAttributes</span><span style="color:#68747D;">(</span><span style="color:#101820;">telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;order.id&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;1234&quot;</span><span style="color:#68747D;">))</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // ...</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>If there is no active span in the context, a no-op span is returned, so it is always safe to call.</p><h2 id="metrics" tabindex="-1">Metrics <a class="header-anchor" href="#metrics" aria-label="Permalink to “Metrics”">​</a></h2><p>To record metrics, request a meter from the <code>Telemetry</code> facade using the <code>Meter</code> method, then create instruments from it. Instruments are safe for concurrent use and should be created once and reused, a common pattern is to create them when the service is constructed and record values in its methods.</p><p>Like <code>Tracer</code>, the <code>Meter</code> argument is the <strong>instrumentation scope name</strong> that identifies the code producing the metrics (see <a href="#creating-spans">Creating Spans</a>). It is recorded as <code>otel.scope.name</code> on the exported metrics.</p><p>The following service uses a <strong>counter</strong> (a value that only goes up, ideal for counting processed payments or sent emails) and a <strong>histogram</strong> (a distribution of values, such as durations or payload sizes):</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">app/services/payment_service.go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">package services</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">context</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">time</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">go.opentelemetry.io/otel/metric</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">github.com/goravel/framework/telemetry</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">goravel/app/facades</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">type PaymentService struct </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    processed metric</span><span style="color:#68747D;">.</span><span style="color:#101820;">Int64Counter</span></span>
<span class="line"><span style="color:#101820;">    duration  metric</span><span style="color:#68747D;">.</span><span style="color:#101820;">Float64Histogram</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#0077B3;">NewPaymentService</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> (*</span><span style="color:#101820;">PaymentService</span><span style="color:#68747D;">,</span><span style="color:#101820;"> error</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">    meter </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Telemetry</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Meter</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;app&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    processed</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> meter</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Int64Counter</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;payments.processed&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#101820;">        metric</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithDescription</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;Number of processed payments&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    )</span></span>
<span class="line"><span style="color:#101820;">    if err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">        return nil</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err</span></span>
<span class="line"><span style="color:#68747D;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    duration</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> meter</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Float64Histogram</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;payments.duration&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#101820;">        metric</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithUnit</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;s&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#101820;">        metric</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithDescription</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;Duration of payment processing&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    )</span></span>
<span class="line"><span style="color:#101820;">    if err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">        return nil</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err</span></span>
<span class="line"><span style="color:#68747D;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    return </span><span style="color:#68747D;">&amp;</span><span style="color:#101820;">PaymentService</span><span style="color:#68747D;">{</span><span style="color:#101820;">processed</span><span style="color:#68747D;">:</span><span style="color:#101820;"> processed</span><span style="color:#68747D;">,</span><span style="color:#101820;"> duration</span><span style="color:#68747D;">:</span><span style="color:#101820;"> duration</span><span style="color:#68747D;">},</span><span style="color:#101820;"> nil</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">r </span><span style="color:#68747D;">*</span><span style="color:#101820;">PaymentService</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Charge</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx context</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">,</span><span style="color:#101820;"> method </span><span style="color:#101820;">string</span><span style="color:#68747D;">)</span><span style="color:#101820;"> error </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    start </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> time</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Now</span><span style="color:#68747D;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // Charge the payment...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    r</span><span style="color:#68747D;">.</span><span style="color:#101820;">processed</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Add</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> 1,</span><span style="color:#101820;"> metric</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithAttributes</span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">        telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;payment.method&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> method</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    ))</span></span>
<span class="line"><span style="color:#101820;">    r</span><span style="color:#68747D;">.</span><span style="color:#101820;">duration</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Record</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> time</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Since</span><span style="color:#68747D;">(</span><span style="color:#101820;">start</span><span style="color:#68747D;">).</span><span style="color:#0077B3;">Seconds</span><span style="color:#68747D;">())</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    return nil</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br></div></div><p>An <strong>up-down counter</strong> can also decrease, useful for tracking in-flight values:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">inFlight</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> meter</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Int64UpDownCounter</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;jobs.in_flight&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">inFlight</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Add</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> 1)</span></span>
<span class="line"><span style="color:#101820;">defer inFlight</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Add</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> -1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>An <strong>observable gauge</strong> reports a value that is sampled rather than recorded, such as a queue depth or the number of open connections. Instead of calling it yourself, you register a callback that is invoked on every collection cycle:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">_</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> meter</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Int64ObservableGauge</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;queue.depth&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#101820;">    metric</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithInt64Callback</span><span style="color:#68747D;">(</span><span style="color:#101820;">func</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx context</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">,</span><span style="color:#101820;"> observer metric</span><span style="color:#68747D;">.</span><span style="color:#101820;">Int64Observer</span><span style="color:#68747D;">)</span><span style="color:#101820;"> error </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">        observer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Observe</span><span style="color:#68747D;">(</span><span style="color:#101820;">int64</span><span style="color:#68747D;">(</span><span style="color:#101820;">queue</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Len</span><span style="color:#68747D;">()))</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">        return nil</span></span>
<span class="line"><span style="color:#68747D;">    }),</span></span>
<span class="line"><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Metrics are collected and pushed to the exporter periodically based on the <code>metrics.reader.interval</code> configuration.</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to “Logs”">​</a></h2><p>During installation, an <code>otel</code> channel is added to your <code>config/logging.go</code> file:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;otel&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;driver&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;">          &quot;otel&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">    &quot;instrument_name&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">GetString</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;APP_NAME&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;goravel/log&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Add the channel to your logging stack and every entry written through <code>facades.Log()</code> will also be exported as an OpenTelemetry log record, with levels, structured fields, and stack traces mapped automatically:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;stack&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;driver&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;">   &quot;stack&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">    &quot;channels&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> []</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;daily&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;otel&quot;</span><span style="color:#68747D;">},</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>To correlate logs with the active trace, write them using <code>WithContext</code>, the trace and span IDs are attached to the record so your backend can link logs to the exact request that produced them:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">r </span><span style="color:#68747D;">*</span><span style="color:#101820;">OrderController</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Store</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">)</span><span style="color:#101820;"> http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Response </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Log</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">WithContext</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">).</span></span>
<span class="line"><span style="color:#0077B3;">        With</span><span style="color:#68747D;">(</span><span style="color:#101820;">map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">            &quot;order_id&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> ctx</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Request</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Input</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;order_id&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">        }).</span></span>
<span class="line"><span style="color:#0077B3;">        Info</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;order received&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // ...</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>You can also temporarily stop exporting logs without touching your logging configuration by setting <code>telemetry.instrumentation.log.enabled</code> to <code>false</code>. If you need full control over the emitted records, you may bypass the logging facade and emit OpenTelemetry log records directly using <code>facades.Telemetry().Logger(&quot;app&quot;)</code>.</p><h2 id="automatic-instrumentation" tabindex="-1">Automatic Instrumentation <a class="header-anchor" href="#automatic-instrumentation" aria-label="Permalink to “Automatic Instrumentation”">​</a></h2><p>Goravel ships with built-in instrumentation for the most common components. Each one can be toggled in the <code>instrumentation</code> section of <code>config/telemetry.go</code>.</p><h3 id="http-server" tabindex="-1">HTTP Server <a class="header-anchor" href="#http-server" aria-label="Permalink to “HTTP Server”">​</a></h3><p>The HTTP server middleware extracts the incoming trace context, starts a server span for every request, and records standard metrics (<code>http.server.request.duration</code>, <code>http.server.request.body.size</code>, <code>http.server.response.body.size</code>). Register it in the <code>bootstrap/app.go</code> file:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">    telemetryhttp </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/telemetry/instrumentation/http</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#0077B3;">Boot</span><span style="color:#68747D;">()</span><span style="color:#101820;"> contractsfoundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    return foundation</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Setup</span><span style="color:#68747D;">().</span></span>
<span class="line"><span style="color:#0077B3;">        WithMiddleware</span><span style="color:#68747D;">(</span><span style="color:#101820;">func</span><span style="color:#68747D;">(</span><span style="color:#101820;">handler configuration</span><span style="color:#68747D;">.</span><span style="color:#101820;">Middleware</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">            handler</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Append</span><span style="color:#68747D;">(</span><span style="color:#101820;">telemetryhttp</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Telemetry</span><span style="color:#68747D;">())</span></span>
<span class="line"><span style="color:#68747D;">        }).</span></span>
<span class="line"><span style="color:#0077B3;">        Create</span><span style="color:#68747D;">()</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>You can skip noisy endpoints using the <code>excluded_paths</code> and <code>excluded_methods</code> configuration options:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;http_server&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;enabled&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">          config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;OTEL_HTTP_SERVER_ENABLED&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> true</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    &quot;excluded_paths&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;">   []</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;/health&quot;</span><span style="color:#68747D;">},</span></span>
<span class="line"><span style="color:#68747D;">    &quot;excluded_methods&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> []</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;OPTIONS&quot;</span><span style="color:#68747D;">},</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>For more advanced control, the middleware accepts options: <code>WithFilter</code> to skip requests programmatically, <code>WithSpanNameFormatter</code> to customize span names, and <code>WithMetricAttributes</code> to attach extra attributes to recorded metrics.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">handler</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Append</span><span style="color:#68747D;">(</span><span style="color:#101820;">telemetryhttp</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Telemetry</span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">    telemetryhttp</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithFilter</span><span style="color:#68747D;">(</span><span style="color:#101820;">func</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">)</span><span style="color:#101820;"> bool </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">        return ctx</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Request</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Path</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> !=</span><span style="color:#68747D;"> &quot;/internal&quot;</span></span>
<span class="line"><span style="color:#68747D;">    }),</span></span>
<span class="line"><span style="color:#68747D;">))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="http-client" tabindex="-1">HTTP Client <a class="header-anchor" href="#http-client" aria-label="Permalink to “HTTP Client”">​</a></h3><p>Outgoing requests made through the <a href="./http-client.html">HTTP Client</a> are instrumented automatically, no setup required. The active trace context is injected into outgoing headers, so downstream Goravel services continue the same trace.</p><p>You can disable it globally via <code>telemetry.instrumentation.http_client.enabled</code>, or per client by setting <code>enable_telemetry</code> to <code>false</code> in the corresponding client configuration in <code>config/http.go</code>.</p><h3 id="grpc" tabindex="-1">gRPC <a class="header-anchor" href="#grpc" aria-label="Permalink to “gRPC”">​</a></h3><p>gRPC instrumentation is provided through stats handlers. Register them in the <code>bootstrap/app.go</code> file using the <code>WithGrpcServerStatsHandlers</code> and <code>WithGrpcClientStatsHandlers</code> functions:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">google.golang.org/grpc/stats</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    telemetrygrpc </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/telemetry/instrumentation/grpc</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#0077B3;">Boot</span><span style="color:#68747D;">()</span><span style="color:#101820;"> contractsfoundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    return foundation</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Setup</span><span style="color:#68747D;">().</span></span>
<span class="line"><span style="color:#0077B3;">        WithGrpcServerStatsHandlers</span><span style="color:#68747D;">(</span><span style="color:#101820;">func</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> []</span><span style="color:#101820;">stats</span><span style="color:#68747D;">.</span><span style="color:#101820;">Handler </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">            return </span><span style="color:#68747D;">[]</span><span style="color:#101820;">stats</span><span style="color:#68747D;">.</span><span style="color:#101820;">Handler</span><span style="color:#68747D;">{</span><span style="color:#101820;">telemetrygrpc</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">NewServerStatsHandler</span><span style="color:#68747D;">()}</span></span>
<span class="line"><span style="color:#68747D;">        }).</span></span>
<span class="line"><span style="color:#0077B3;">        WithGrpcClientStatsHandlers</span><span style="color:#68747D;">(</span><span style="color:#101820;">func</span><span style="color:#68747D;">()</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">][]</span><span style="color:#101820;">stats</span><span style="color:#68747D;">.</span><span style="color:#101820;">Handler </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">            return map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">][]</span><span style="color:#101820;">stats</span><span style="color:#68747D;">.</span><span style="color:#101820;">Handler</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">                &quot;default&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> {</span><span style="color:#101820;">telemetrygrpc</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">NewClientStatsHandler</span><span style="color:#68747D;">()},</span></span>
<span class="line"><span style="color:#68747D;">            }</span></span>
<span class="line"><span style="color:#68747D;">        }).</span></span>
<span class="line"><span style="color:#0077B3;">        Create</span><span style="color:#68747D;">()</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>Both handlers accept options such as <code>WithFilter</code>, <code>WithSpanAttributes</code>, and <code>WithMetricAttributes</code>, and can be toggled via the <code>grpc_server.enabled</code> and <code>grpc_client.enabled</code> configuration options.</p><h3 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to “Database”">​</a></h3><p>Queries executed through the <a href="./../orm/getting-started.html">ORM</a> (<code>facades.Orm()</code>) and the <a href="./../database/queries.html">Query Builder</a> (<code>facades.DB()</code>) are instrumented automatically, no setup required. Each query records a client span along with the <code>db.client.operation.duration</code> metric, and every connection pool reports <code>db.client.connection.count</code> and <code>db.client.connection.max</code>, so you can watch pool usage and saturation.</p><p>You can disable it via the <code>telemetry.instrumentation.database.enabled</code> configuration option (the <code>OTEL_DATABASE_ENABLED</code> environment variable).</p><p>For structured queries, the table comes from the builder, so the span is named after the operation and table and carries the <code>db.collection.name</code> attribute. Nothing extra is required:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">DB</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Table</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;users&quot;</span><span style="color:#68747D;">).</span><span style="color:#0077B3;">Where</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;id&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> 1).</span><span style="color:#0077B3;">Get</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">users</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> // span: SELECT users</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Raw queries run through <code>Select</code> or <code>Statement</code> pass an opaque SQL string that the framework does not parse, so the span is named after the operation alone. Use <code>ContextWithTable</code> to tag the table onto the request context to restore the full name and the <code>db.collection.name</code> attribute:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">    instrumentationdatabase </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/telemetry/instrumentation/database</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">queryCtx </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> instrumentationdatabase</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">ContextWithTable</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;users&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">DB</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">WithContext</span><span style="color:#68747D;">(</span><span style="color:#101820;">queryCtx</span><span style="color:#68747D;">).</span><span style="color:#0077B3;">Select</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">users</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;SELECT * FROM users WHERE id = ?&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> 1)</span><span style="color:#68747D;"> // span: SELECT users</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="context-propagation" tabindex="-1">Context Propagation <a class="header-anchor" href="#context-propagation" aria-label="Permalink to “Context Propagation”">​</a></h2><p>The <code>propagators</code> configuration option defines how trace context crosses process boundaries. The default is the W3C <code>tracecontext</code> standard; <code>baggage</code>, <code>b3</code>, and <code>b3multi</code> (Zipkin) are also supported and can be combined as a comma-separated list.</p><p>The built-in HTTP and gRPC instrumentation propagate context automatically. If you communicate over a custom transport, such as a message queue, you can carry the trace across the boundary yourself using the <code>Propagator</code> method: the producer injects the active context into the message headers, and the consumer extracts it and continues the same trace:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">context</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">github.com/goravel/framework/telemetry</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">goravel/app/facades</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">type Message struct </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    Headers map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">string</span></span>
<span class="line"><span style="color:#101820;">    Body    </span><span style="color:#68747D;">[]</span><span style="color:#101820;">byte</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">r </span><span style="color:#68747D;">*</span><span style="color:#101820;">OrderPublisher</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Publish</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx context</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">,</span><span style="color:#101820;"> message </span><span style="color:#68747D;">*</span><span style="color:#101820;">Message</span><span style="color:#68747D;">)</span><span style="color:#101820;"> error </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    // Attach the active trace context to the message</span></span>
<span class="line"><span style="color:#101820;">    facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Telemetry</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Propagator</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Inject</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">PropagationMapCarrier</span><span style="color:#68747D;">(</span><span style="color:#101820;">message</span><span style="color:#68747D;">.</span><span style="color:#101820;">Headers</span><span style="color:#68747D;">))</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">    // Send the message to the broker...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    return nil</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">r </span><span style="color:#68747D;">*</span><span style="color:#101820;">OrderConsumer</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Consume</span><span style="color:#68747D;">(</span><span style="color:#101820;">message </span><span style="color:#68747D;">*</span><span style="color:#101820;">Message</span><span style="color:#68747D;">)</span><span style="color:#101820;"> error </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    // Continue the trace started by the producer</span></span>
<span class="line"><span style="color:#101820;">    ctx </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Telemetry</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Propagator</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Extract</span><span style="color:#68747D;">(</span><span style="color:#101820;">context</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Background</span><span style="color:#68747D;">(),</span><span style="color:#101820;"> telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">PropagationMapCarrier</span><span style="color:#68747D;">(</span><span style="color:#101820;">message</span><span style="color:#68747D;">.</span><span style="color:#101820;">Headers</span><span style="color:#68747D;">))</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> span </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Telemetry</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Tracer</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;app&quot;</span><span style="color:#68747D;">).</span><span style="color:#0077B3;">Start</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;orders.consume&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#101820;">        telemetry</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithSpanKind</span><span style="color:#68747D;">(</span><span style="color:#101820;">telemetry</span><span style="color:#68747D;">.</span><span style="color:#101820;">SpanKindConsumer</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    )</span></span>
<span class="line"><span style="color:#101820;">    defer span</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">End</span><span style="color:#68747D;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">    return r</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">process</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> message</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br></div></div><p>If you need the identifiers of the current trace, for example, to return them in an error response, you can read them from the context:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">go.opentelemetry.io/otel/trace</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">spanCtx </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> trace</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">SpanContextFromContext</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">traceID </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> spanCtx</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">TraceID</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">()</span></span>
<span class="line"><span style="color:#101820;">spanID </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> spanCtx</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">SpanID</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="flushing-shutdown" tabindex="-1">Flushing &amp; Shutdown <a class="header-anchor" href="#flushing-shutdown" aria-label="Permalink to “Flushing &amp; Shutdown”">​</a></h2><p>You don&#39;t need to manage the telemetry lifecycle yourself: when the application stops, Goravel automatically flushes all buffered data and shuts the providers down, waiting at most <code>shutdown_timeout</code> (default <code>15s</code>).</p><p>If you need to push buffered data immediately without stopping the providers, for example, before a serverless function freezes, you can use the <code>ForceFlush</code> method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">ctx</span><span style="color:#68747D;">,</span><span style="color:#101820;"> cancel </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> context</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">WithTimeout</span><span style="color:#68747D;">(</span><span style="color:#101820;">context</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Background</span><span style="color:#68747D;">(),</span><span style="color:#68747D;"> 10*</span><span style="color:#101820;">time</span><span style="color:#68747D;">.</span><span style="color:#101820;">Second</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">defer </span><span style="color:#0077B3;">cancel</span><span style="color:#68747D;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">if err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Telemetry</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">ForceFlush</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx</span><span style="color:#68747D;">);</span><span style="color:#101820;"> err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Log</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Error</span><span style="color:#68747D;">(</span><span style="color:#101820;">err</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div>`,125)]))}const b=n(o,[["render",p]]);export{d as __pageData,b as default};
